import { expect, expectStatus, test } from "../../fixtures";

type VendorBody = { id: string; status: string };
type DocumentBody = { id: string; kind: string; status: string };
type ExtractionBody = { id: string; document_id: string; kind: string; status: string };
type ReviewQueueBody = Array<{ vendor_id: string }>;

test("an admin can review vendors", { tag: "@LIF-12" }, async ({ apiAs }) => {
  // Arrange: an admin creates a vendor with one document of each kind, then submits it for review.
  const admin = await apiAs("admin");
  const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

  const vendor = await expectStatus<VendorBody>(
    await admin.post("/api/vendors", {
      data: {
        name: `LIF-12 Review Vendor ${suffix}`,
        category: "services",
        contact_email: `lif12-review-${suffix}@example.test`,
      },
    }),
    201,
  );

  const documentIds: Record<string, string> = {};
  for (const kind of ["w9", "insurance_certificate", "contract"]) {
    const doc = await expectStatus<DocumentBody>(
      await admin.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: {
            name: `${kind}-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 lif-12 test document"),
          },
        },
      }),
      201,
    );
    documentIds[kind] = doc.id;
  }

  // Wait for extraction of each document, then confirm each extraction is pending review.
  const extractions: Record<string, ExtractionBody> = {};
  for (const [kind, documentId] of Object.entries(documentIds)) {
    await expect
      .poll(
        async () =>
          (await expectStatus<DocumentBody>(await admin.get(`/api/documents/${documentId}`), 200)).status,
        { timeout: 60_000 },
      )
      .toBe("extracted");

    const extraction = await expectStatus<ExtractionBody>(
      await admin.get(`/api/documents/${documentId}/extraction`),
      200,
    );
    expect(extraction.status).toBe("pending_review");
    extractions[kind] = extraction;
  }

  const submitted = await expectStatus<VendorBody>(
    await admin.post(`/api/vendors/${vendor.id}/submit`),
    200,
  );
  expect(submitted.status).toBe("in_review");

  // Act: approve the w9 extraction and open the review queue.
  const decision = await expectStatus<ExtractionBody>(
    await admin.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "approve", note: `LIF-12 approval ${suffix}` },
    }),
    200,
  );
  expect(decision.status).toBe("approved");

  const queueResponse = await admin.get("/api/review-queue");

  // Assert
  const queue = await expectStatus<ReviewQueueBody>(queueResponse, 200);
  expect(queue.map((item) => item.vendor_id)).toContain(vendor.id);
});
